#include "stdlib/stats/base/dists/signrank/quantile.h"
#include "stdlib/constants/float64/ln_two.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/exp.h"
#include "stdlib/math/base/assert/is_finite.h"
#include "stdlib/math/base/assert/is_positive_integer.h"
#include <stdint.h>

/**
* Calculates the weight for the (x,n) pair and memoizes the result.
*
* @param x   input value
* @param n   number of observations (must be a non-negative)
* @return    weight value
*/
static double weights( double x, const int32_t n ) {
	double mlim;

	if ( n == 0 ) {
		return ( x == 0 ) ? 1.0 : 0.0;
	}
	mlim = ( (double)n * ( (double)n + 1.0 ) ) / 2.0;
	if ( x < 0 || x > mlim ) {
		return 0.0;
	}
	if ( x > mlim / 2.0 ) {
		x = mlim - x;
	}
	return weights( x - (double)n, n - 1 ) + weights( x, n - 1 );
}

/**
* Evaluates the quantile function of the Wilcoxon signed rank test statistic with `n` observations.
*
* @param p   input value
* @param n   number of observations
* @returns   evaluated quantile function
*
* @example
* var y = stdlib_base_dists_signrank_quantile( 0.8, 5 );
* // returns 11
*/

double stdlib_base_dists_signrank_quantile( const double p, const int32_t n ) {
	double pui;
	double q;
	double r;
	if ( stdlib_base_is_nan( n ) || !stdlib_base_is_positive_integer( n ) || !stdlib_base_is_finite( n ) ) {
		return 0.0 / 0.0; // NaN
	}
	if ( stdlib_base_is_nan( p ) || p < 0.0 || p > 1.0 ) {
		return 0.0 / 0.0;
	}
	if ( p == 0.0 ) {
		return 0;
	}
	if ( p == 1.0 ) {
		return ( n * ( n + 1 ) ) / 2;
	}
	pui = stdlib_base_exp( -n * STDLIB_CONSTANT_FLOAT64_LN2 );
	r = 0;
	q = -1;
	while ( r < p ) {
		q += 1;
		r += pui * weights( q, n );
	}
	return q;
}
